/* Banco de preguntas - Celador/a SERGAS - Parte específica (temas 4 a 10)
   Mismo formato que preguntas-1.js. Añadir las nuevas al final de cada tema. */

/* ================= TEMA 4: Área quirúrgica, hospitalización, estancias comunes, salud mental ================= */
B(4,"T","En la distribución del bloque quirúrgico, el quirófano propiamente dicho se encuentra en la:","Zona blanca o estéril",["Zona negra o sin restricciones","Zona gris o limpia","Zona verde o de tránsito"],"Negra: sin restricción; gris: limpia o semirrestringida; blanca: estéril o restringida.");
B(4,"T","La zona del bloque quirúrgico por la que se accede con ropa de calle y donde se encuentran los vestuarios es la:","Zona negra",["Zona gris","Zona blanca","Zona estéril"],"Es la zona de acceso, sin limitaciones de vestimenta.");
B(4,"T","Para evitar la entrada de aire contaminado, la presión del aire dentro del quirófano respecto a las zonas adyacentes debe ser:","Positiva",["Negativa","Igual","Variable según la intervención"],"La presión positiva hace que el aire fluya del quirófano hacia fuera y no al revés.");
B(4,"T","Señale la INCORRECTA sobre el celador de quirófano:","Forma parte del personal estéril del equipo quirúrgico",["Viste pijama, gorro, mascarilla y calzas","Traslada al paciente hasta la mesa de operaciones","Colabora en la colocación del paciente siguiendo indicaciones"],"El celador es personal no estéril; no debe tocar ni rozar el campo ni el material estéril.");
B(4,"T","La mascarilla quirúrgica debe colocarse:","Cubriendo nariz, boca y mentón",["Cubriendo solo la boca","Colgada del cuello hasta entrar en el quirófano","Por debajo de la nariz para respirar mejor"],"Debe cambiarse si se humedece y no llevarse colgada.");
B(4,"T","El gorro quirúrgico debe:","Cubrir completamente todo el cabello",["Dejar al descubierto el flequillo","Usarse solo por el personal estéril","Colocarse después de entrar al quirófano"],"El cabello es una fuente importante de contaminación.");
B(4,"T","Durante la intervención quirúrgica, las puertas del quirófano deben permanecer:","Cerradas, limitando las entradas y salidas a las imprescindibles",["Abiertas para facilitar la ventilación","Entreabiertas","Abiertas solo la puerta de sucio"],"Abrir puertas altera la presión positiva y aumenta el riesgo de contaminación.");
B(4,"T","La destrucción de todos los microorganismos, incluidas las esporas, se denomina:","Esterilización",["Desinfección","Antisepsia","Limpieza"],"La desinfección no garantiza la eliminación de esporas.");
B(4,"T","El conjunto de procedimientos destinados a eliminar o inhibir microorganismos patógenos sobre tejidos vivos se denomina:","Antisepsia",["Desinfección","Esterilización","Desinsectación"],"La desinfección se aplica sobre objetos y superficies inanimados.");
B(4,"T","La ausencia de microorganismos patógenos se denomina:","Asepsia",["Sepsis","Antisepsia","Contaminación"],"La asepsia es el estado; la antisepsia, el procedimiento sobre tejido vivo.");
B(4,"T","El periodo que transcurre desde que el paciente entra en el quirófano hasta que sale hacia la unidad de recuperación se denomina:","Intraoperatorio",["Preoperatorio","Postoperatorio","Perioperatorio tardío"],"El perioperatorio engloba pre, intra y postoperatorio.");
B(4,"T","Las siglas URPA corresponden a:","Unidad de Recuperación Postanestésica",["Unidad de Reanimación y Parada","Unidad de Recepción de Pacientes Ambulatorios","Unidad de Radiología y Pruebas Analíticas"],"También llamada sala de despertar.");
B(4,"T","¿Qué tipo de higiene de manos corresponde al celador de quirófano?","Lavado higiénico de manos",["Lavado quirúrgico","Ninguno, porque usa guantes","Solo desinfección con yodo"],"El lavado quirúrgico lo realiza el personal estéril (cirujanos e instrumentista).");
B(4,"T","Para pasar al paciente de la cama a la mesa quirúrgica reduciendo el esfuerzo se utiliza habitualmente:","El transfer",["La camilla de cuchara","El marco de Balkan","La silla de ruedas"],"En muchos bloques quirúrgicos existe además una zona de transferencia entre el pasillo limpio y el exterior.");
B(4,"T","La posición quirúrgica más habitual, por ser la de la mayoría de intervenciones abdominales y torácicas anteriores, es:","Decúbito supino",["Decúbito prono","Kraske","Genupectoral"],"Es además la posición en la que se suele inducir la anestesia general.");
B(4,"T","En las intervenciones ginecológicas por vía vaginal y en muchas urológicas se coloca a la paciente en posición de:","Litotomía",["Kraske","Roser","Fowler"],"Con las piernas en perneras o estribos.");
B(4,"T","Señale la INCORRECTA. Es función del celador en quirófano:","Entregar el instrumental estéril al cirujano",["Trasladar al paciente desde su unidad al quirófano","Transportar muestras y hemoderivados cuando se le indique","Ayudar a colocar al paciente en la mesa quirúrgica"],"La instrumentación corresponde a la enfermera instrumentista.");
B(4,"T","En una unidad de hospitalización, el celador traslada al paciente a las pruebas diagnósticas acompañado de:","La documentación clínica que le entregue el personal de enfermería",["Ninguna documentación","La medicación del turno","Los objetos de valor del paciente"],"El celador traslada la documentación sin consultarla y la entrega en el servicio de destino.");
B(4,"T","La indicación de una contención mecánica en un paciente agitado corresponde a:","El médico",["El celador","El familiar","El vigilante de seguridad"],"En urgencia puede iniciarla enfermería comunicándolo de inmediato al médico; el celador nunca la decide.");
B(4,"T","Para realizar una contención mecánica completa con seguridad se recomienda un equipo de:","Cuatro o cinco personas",["Una persona","Dos personas","Ocho personas"],"Una por extremidad y, a ser posible, otra para la cabeza.");
B(4,"T","Como norma general, el paciente sometido a contención mecánica se coloca en:","Decúbito supino, con la cabecera ligeramente elevada",["Decúbito prono","Trendelenburg","Sedestación"],"Disminuye el riesgo de aspiración y permite la vigilancia.");
B(4,"T","En la sujeción completa de un paciente se inmovilizan:","El tronco y las cuatro extremidades",["Solo las muñecas","El tronco y una extremidad","Solo los tobillos"],"En la parcial se sujetan el tronco y dos extremidades en diagonal.");
B(4,"T","El internamiento no voluntario por razón de trastorno psíquico está regulado en:","El artículo 763 de la Ley de Enjuiciamiento Civil",["El artículo 14 de la Constitución","La Ley 55/2003","El Estatuto de Personal No Sanitario"],"Requiere autorización judicial, previa o posterior si es urgente.");
B(4,"T","En un internamiento involuntario urgente, el responsable del centro debe comunicarlo al juzgado en un plazo máximo de:","24 horas",["12 horas","48 horas","72 horas"],"El juez dispone de un máximo de 72 horas para ratificar la medida.");
B(4,"T","Señale la INCORRECTA sobre la actuación del celador en una unidad de salud mental:","Decide cuándo retirar la contención al paciente",["Vigila que los pacientes no accedan a objetos peligrosos","Colabora en las contenciones cuando se le requiere","Acompaña a los pacientes en los traslados"],"La retirada de la contención la decide el personal sanitario.");
B(4,"T","Ante un paciente psiquiátrico agitado, la primera medida que debe intentarse es:","La contención verbal",["La contención mecánica","El aislamiento","La contención farmacológica por el celador"],"La contención mecánica es siempre el último recurso.");
B(4,"P","Va a entrar en la zona limpia del bloque quirúrgico para recoger a un paciente. Antes debe:","Ponerse pijama quirúrgico, gorro, calzas y mascarilla según la zona",["Entrar con su uniforme de planta","Ponerse solo guantes","Entrar con bata encima del uniforme"],"La indumentaria quirúrgica es obligatoria a partir de la zona limpia.");
B(4,"P","Está en el quirófano y, al acercar un aparato, roza con el brazo la mesa de instrumental estéril. Lo correcto es:","Comunicarlo de inmediato al personal de enfermería",["No decir nada si nadie lo ha visto","Limpiar la zona con una gasa","Salir del quirófano sin avisar"],"El material rozado se considera contaminado y debe sustituirse.");
B(4,"P","Durante una intervención le entregan una muestra para anatomía patológica. Debe:","Trasladarla sin demora al servicio indicado, correctamente identificada y con su volante",["Guardarla hasta el final de la jornada","Dejarla en el control de planta","Abrirla para comprobar su contenido"],"El traslado de muestras debe ser inmediato y con su documentación.");
B(4,"P","Traslada a un paciente a quirófano y este le pregunta, nervioso, en qué consiste exactamente su operación. Usted:","Le tranquiliza y le indica que el personal sanitario le resolverá sus dudas",["Le explica lo que sabe de la intervención","Le dice que es una operación sin importancia","No le contesta"],"El trato debe ser amable, pero la información clínica corresponde a los profesionales sanitarios.");
B(4,"P","En la unidad de psiquiatría, un paciente comienza a mostrarse agresivo verbalmente. Usted está solo con él. Debe:","Mantener la calma, guardar distancia de seguridad y avisar al personal sanitario",["Sujetarle usted solo","Gritarle para que se calme","Encerrarlo y marcharse"],"No se debe intentar reducir a un paciente en solitario.");
B(4,"P","Le requieren para una contención mecánica. El enfermero dirige la maniobra. Su papel será:","Sujetar la extremidad que se le asigne siguiendo las instrucciones de quien dirige",["Decidir qué correas colocar","Administrar la medicación","Hablar con el paciente para convencerle"],"Durante la contención solo una persona dirige y habla con el paciente.");
B(4,"P","Al recoger a un paciente en planta para llevarlo a quirófano, observa que lleva prótesis dental y un reloj. Usted:","Lo comunica al personal de enfermería de la unidad antes de salir",["Se los retira y los guarda usted","No hace nada","Se los entrega al cirujano"],"La preparación preoperatoria es responsabilidad de enfermería.");
B(4,"P","Finalizada la intervención, debe trasladar al paciente a la URPA. Irá acompañado de:","El anestesista y/o personal de enfermería",["Solo el celador","Un familiar","Nadie; irá el celador con la historia"],"El paciente recién intervenido debe ir vigilado por personal sanitario.");

/* ================= TEMA 5: Pacientes fallecidos, salas de autopsias, mortuorios ================= */
B(5,"T","Los cuidados post mortem o amortajamiento son responsabilidad de:","El personal de enfermería, con la colaboración del celador",["El celador exclusivamente","El personal de la funeraria","Los familiares"],"El celador ayuda a movilizar el cadáver y lo traslada al mortuorio.");
B(5,"T","El amortajamiento debe realizarse:","Antes de que aparezca la rigidez cadavérica",["Cuando llegue la funeraria","Pasadas 24 horas","Después de la autopsia en todo caso"],"El rigor mortis dificulta la manipulación del cadáver.");
B(5,"T","El enfriamiento progresivo del cadáver se denomina:","Algor mortis",["Rigor mortis","Livor mortis","Éxitus"],"Rigor mortis: rigidez; livor mortis: livideces.");
B(5,"T","Las manchas violáceas que aparecen en las zonas declives del cadáver se denominan:","Livor mortis o livideces cadavéricas",["Rigor mortis","Algor mortis","Equimosis traumáticas"],"Se deben al depósito de sangre por gravedad.");
B(5,"T","El término 'éxitus' significa:","Fallecimiento",["Alta voluntaria","Traslado a otro centro","Éxito de la intervención"],"Del latín exitus letalis.");
B(5,"T","La pieza de tela o bolsa en la que se envuelve el cadáver se denomina:","Sudario",["Entremetida","Hule","Empapador"],"Sobre él se coloca la identificación del fallecido.");
B(5,"T","Para amortajar, el cadáver se coloca en:","Decúbito supino",["Decúbito prono","Decúbito lateral","Posición de Fowler"],"Con la cama en posición horizontal y el cuerpo alineado.");
B(5,"T","La autopsia que se realiza por orden judicial se denomina:","Autopsia médico-legal o forense",["Autopsia clínica","Autopsia anatomopatológica","Biopsia"],"No requiere autorización de la familia.");
B(5,"T","Señale la INCORRECTA sobre la autopsia clínica:","La ordena el juez y la realiza el médico forense",["Busca conocer o confirmar las causas de la muerte por enfermedad","La realiza el médico anatomopatólogo","Está regulada por la Ley 29/1980 y el Real Decreto 2230/1982"],"La autopsia ordenada por el juez es la judicial o forense.");
B(5,"T","Las autopsias clínicas están reguladas por:","La Ley 29/1980, de 21 de junio",["La Ley 14/1986, de 25 de abril","La Ley 41/2002, de 14 de noviembre","La Ley 31/1995, de 8 de noviembre"],"Desarrollada por el Real Decreto 2230/1982.");
B(5,"T","Es sinónimo de autopsia:","Necropsia",["Biopsia","Tanatopraxia","Tanatoestética"],"También tanatopsia o examen post mortem.");
B(5,"T","Tras la autopsia, corresponde al celador:","Limpiar la mesa de autopsias y la propia sala",["Redactar el informe","Suturar el cadáver","Tomar las muestras"],"Función 20ª del artículo 14.2 del Estatuto de Personal No Sanitario.");
B(5,"T","La norma estatal que regula la policía sanitaria mortuoria es:","El Decreto 2263/1974, de 20 de julio",["La Ley 29/1980, de 21 de junio","El Real Decreto 2230/1982","La Ley 14/1986"],"En Galicia rige además el Decreto 129/2023, de sanidad mortuoria.");
B(5,"T","En Galicia, la sanidad mortuoria está regulada por:","El Decreto 129/2023, de 31 de agosto",["La Ley 8/2008, de 10 de julio","El Decreto 2263/1974, de 20 de julio","La Ley 3/2001, de 28 de mayo"],"Sustituyó al Decreto 151/2014. La Ley 8/2008 es la de salud de Galicia y la Ley 3/2001 la del consentimiento informado e historia clínica.");
B(5,"T","Se considera 'cadáver' el cuerpo humano durante:","Los cinco años siguientes a la muerte real",["El primer año tras la muerte","Los diez años siguientes a la muerte","Las 48 horas siguientes a la muerte"],"Pasado ese plazo se habla de restos cadavéricos.");
B(5,"T","El conjunto de técnicas que retrasan o impiden la putrefacción del cadáver se denomina:","Tanatopraxia",["Necropsia","Exhumación","Incineración"],"Comprende la conservación transitoria (retrasa) y el embalsamamiento (impide).");
B(5,"T","Las técnicas de cosmética aplicadas al cadáver para mejorar su aspecto se denominan:","Tanatoestética",["Tanatopsia","Tanatología","Inhumación"],"La tanatología es la ciencia que estudia la muerte.");
B(5,"T","La acción de enterrar un cadáver se denomina:","Inhumación",["Exhumación","Cremación","Embalsamamiento"],"La exhumación es la acción de extraerlo de su sepultura.");
B(5,"T","En Galicia, con carácter general, la inhumación o incineración de un cadáver no puede realizarse antes de transcurridas:","12 horas desde el fallecimiento",["6 horas desde el fallecimiento","24 horas desde el fallecimiento","72 horas desde el fallecimiento"],"Decreto 129/2023: entre las 12 y las 48 horas, salvo excepciones. El reglamento estatal de 1974 fijaba 24 horas.");
B(5,"T","El traslado del cadáver desde la unidad al mortuorio se hará:","Cubierto, con discreción y por las zonas menos transitadas",["Descubierto para su identificación","Por el vestíbulo principal","En silla de ruedas"],"Debe preservarse la intimidad y evitar el impacto a otros pacientes y visitantes.");
B(5,"T","Señale la INCORRECTA. En los cuidados post mortem, el celador:","Retira las sondas, drenajes y vías del cadáver",["Ayuda a movilizar el cadáver","Traslada el cadáver al mortuorio","Ayuda a pasarlo a la camilla"],"La retirada de sondas, drenajes y catéteres corresponde a enfermería.");
B(5,"T","La recogida y entrega a la familia de los objetos personales del fallecido corresponde a:","El personal de enfermería, según el procedimiento del centro",["El celador que traslada el cadáver","La funeraria","El personal de limpieza"],"El celador no debe hacerse cargo de los objetos de valor.");
B(5,"T","El lugar del hospital donde permanecen los cadáveres hasta su retirada por la funeraria es:","El mortuorio",["La sala de autopsias","El almacén general","La URPA"],"Dispone de cámaras frigoríficas para la conservación.");
B(5,"P","Fallece un paciente en una habitación compartida. Antes de iniciar los cuidados post mortem, lo adecuado es:","Aislar la cama con biombo o cortina, o trasladar al otro paciente si es posible",["Realizarlos a la vista del compañero","Pedir al otro paciente que ayude","Esperar a la noche"],"Debe preservarse la intimidad del fallecido y evitar el impacto al otro paciente.");
B(5,"P","Los familiares de un fallecido le preguntan por los trámites para el entierro. Según el Estatuto de Personal No Sanitario, esa información corresponde a:","El Jefe de Personal Subalterno",["El celador, que debe conocerlos","El médico de guardia","La funeraria exclusivamente"],"Artículo 14.1 del Estatuto.");
B(5,"P","Al llegar al mortuorio con un cadáver, comprueba que no lleva ninguna identificación. Usted:","Lo comunica a la unidad de procedencia para que se identifique correctamente antes de depositarlo",["Lo deposita igualmente en la cámara","Escribe usted el nombre que recuerda","Lo deja en el pasillo del mortuorio"],"La identificación es imprescindible para evitar errores en la entrega.");
B(5,"P","Le avisan para trasladar un cadáver a la sala de autopsias. Allí, su actuación incluye:","Colocar el cadáver en la mesa y ayudar en tareas auxiliares sin usar instrumental sobre él",["Abrir las cavidades","Extraer los órganos","Tomar muestras de tejidos"],"El uso de instrumental sobre el cadáver no corresponde al celador.");
B(5,"P","Un empleado de una funeraria acude al mortuorio a retirar un cadáver. Usted debe:","Comprobar la documentación y la identidad del cadáver y registrar la salida según el procedimiento",["Entregarlo sin más comprobaciones","Pedirle que vuelva otro día","Dejarle que busque él en las cámaras"],"La entrega debe quedar registrada y verificada.");
B(5,"P","Durante el traslado de un cadáver, un visitante le pregunta de qué ha muerto. Usted:","No facilita ninguna información",["Le dice lo que ha oído en la planta","Le indica el nombre del fallecido","Le remite al tablón de anuncios"],"El deber de confidencialidad se mantiene tras el fallecimiento.");
B(5,"P","Fallece un paciente y el juzgado ha ordenado la autopsia. Respecto al cadáver, lo correcto es:","No manipularlo ni retirar sondas o catéteres, siguiendo las instrucciones recibidas",["Amortajarlo de la forma habitual","Lavarlo a fondo","Entregarlo a la funeraria"],"En las muertes judiciales debe evitarse cualquier manipulación que altere las pruebas.");

/* ================= TEMA 6: Suministros, recepción, almacén, distribución ================= */
B(6,"T","El suministro que va desde el proveedor hasta el almacén del centro sanitario es:","Suministro externo",["Suministro interno","Suministro directo","Autoconsumo"],"El interno va del almacén a las unidades y servicios.");
B(6,"T","El documento que acompaña a la mercancía y acredita su entrega es:","El albarán",["La factura","El presupuesto","El inventario"],"La factura es el documento que acredita la compraventa y su importe.");
B(6,"T","En la recepción de mercancías, el celador debe comprobar:","Que lo recibido coincide con el albarán y con el pedido, y que llega en buen estado",["Solo el número de bultos","Solo el precio","Nada; firma y almacena"],"Las incidencias deben anotarse y comunicarse.");
B(6,"T","El sistema de almacenamiento por el que lo primero que entra es lo primero que sale se denomina:","FIFO",["LIFO","ABC","JIT"],"First In, First Out. LIFO: lo último que entra es lo primero que sale.");
B(6,"T","Para los productos con fecha de caducidad, el criterio de salida más adecuado es:","FEFO: primero sale lo que antes caduca",["LIFO: primero sale lo último que entró","Aleatorio","Primero sale lo más barato"],"First Expired, First Out.");
B(6,"T","La cantidad mínima de un artículo que debe haber en el almacén para evitar el desabastecimiento se denomina:","Stock mínimo o de seguridad",["Stock máximo","Stock cero","Stock muerto"],"Cubre retrasos del proveedor o aumentos imprevistos del consumo.");
B(6,"T","El nivel de existencias a partir del cual debe solicitarse la reposición de un artículo se denomina:","Punto de pedido",["Stock máximo","Rotura de stock","Inventario"],"Tiene en cuenta el plazo de entrega del proveedor.");
B(6,"T","La situación en la que el almacén se queda sin existencias de un artículo se denomina:","Rotura de stock",["Stock de seguridad","Sobrestock","Rotación"],"Es lo que pretende evitar el stock de seguridad.");
B(6,"T","El recuento y valoración de las existencias de un almacén se denomina:","Inventario",["Albarán","Pedido","Expedición"],"Puede ser periódico, permanente o rotativo.");
B(6,"T","En la clasificación ABC de los artículos de un almacén, los artículos del grupo A son:","Pocos artículos que representan la mayor parte del valor",["La mayoría de artículos, de escaso valor","Los artículos caducados","Los artículos sin movimiento"],"Aproximadamente el 20 % de los artículos y el 80 % del valor.");
B(6,"T","En la colocación de mercancías en estanterías, los artículos más pesados se sitúan:","En los niveles inferiores",["En los niveles superiores","En cualquier nivel","Siempre en el suelo de los pasillos"],"Mejora la estabilidad y reduce el riesgo en la manipulación.");
B(6,"T","Los artículos con mayor rotación deben ubicarse:","En las zonas más accesibles",["En el fondo del almacén","En las estanterías más altas","Fuera del almacén"],"Se reduce el tiempo y el esfuerzo de preparación de pedidos.");
B(6,"T","El material que se consume con el uso y no se recupera (gasas, jeringas, guantes) se denomina:","Material fungible",["Material inventariable","Inmovilizado","Material inmueble"],"El inventariable tiene una vida útil prolongada (aparatos, mobiliario).");
B(6,"T","El sistema de reposición en las unidades basado en dos compartimentos por artículo, de modo que se repone al vaciarse uno, se llama:","Doble cajón o doble cubeta",["FIFO","Inventario rotativo","Stock cero"],"Es un sistema tipo Kanban.");
B(6,"T","Señale la INCORRECTA. Es función del celador de almacén:","Negociar los precios con los proveedores",["Descargar y recepcionar las mercancías","Colocar los artículos en su ubicación","Distribuir los pedidos a las unidades"],"La gestión de compras corresponde al servicio de suministros.");
B(6,"T","La zona del almacén donde se preparan los pedidos para las unidades se denomina zona de:","Preparación de pedidos o picking",["Recepción","Devoluciones","Cuarentena"],"Las zonas básicas son recepción, almacenaje, preparación y expedición.");
B(6,"P","Al recibir un pedido comprueba que faltan dos cajas respecto a lo indicado en el albarán. Debe:","Anotar la incidencia en el albarán y comunicarlo al responsable",["Firmar conforme sin más","Rechazar todo el pedido por su cuenta","No decir nada y colocar lo recibido"],"La conformidad debe reflejar lo realmente recibido.");
B(6,"P","Llega un envío de material con el embalaje roto y mojado. Usted:","Lo hace constar al transportista y en el albarán, y avisa al responsable del almacén",["Lo coloca en las estanterías","Lo tira directamente","Lo reparte cuanto antes"],"El material deteriorado no debe incorporarse al stock sin revisión.");
B(6,"P","Coloca en la estantería una nueva partida de un producto con caducidad posterior a la ya existente. Lo correcto es:","Colocar la nueva detrás, dejando delante la que caduca antes",["Colocar la nueva delante","Mezclarlas","Retirar la antigua"],"Así se garantiza que sale primero lo que antes caduca.");
B(6,"P","Una unidad le pide de palabra en el pasillo varios artículos del almacén. Usted:","Indica que debe solicitarlo por el cauce establecido (hoja o sistema de pedidos)",["Se los entrega sin registrar","Se los da si es poca cantidad","Les deja entrar a cogerlos"],"Toda salida de almacén debe quedar registrada.");
B(6,"P","Debe mover una carga muy pesada dentro del almacén. Lo adecuado es:","Utilizar medios mecánicos como la transpaleta o pedir ayuda",["Levantarla usted solo","Arrastrarla doblando la espalda","Dejarla en el pasillo"],"Las ayudas mecánicas son la primera medida preventiva.");
B(6,"P","Al distribuir un pedido a una planta, lo correcto al entregarlo es:","Entregarlo a la persona responsable y recabar su firma de recepción",["Dejarlo en el pasillo","Dejarlo en una habitación vacía","Dárselo a un familiar"],"La entrega debe quedar acreditada.");

/* ================= TEMA 7: Farmacia, documentos y objetos, esterilización, higiene, reprografía ================= */
B(7,"T","El sistema de distribución de medicamentos en dosis unitarias (unidosis) consiste en:","Dispensar a cada paciente la medicación necesaria, normalmente para 24 horas",["Entregar a la planta envases completos para un mes","Que el paciente traiga su medicación","Repartir la medicación una vez por semana"],"El celador traslada los carros de unidosis entre farmacia y las unidades.");
B(7,"T","Los medicamentos termolábiles deben conservarse, con carácter general, entre:","2 y 8 ºC",["-18 y -10 ºC","15 y 25 ºC","30 y 40 ºC"],"Durante el traslado no debe romperse la cadena de frío.");
B(7,"T","Los estupefacientes en el servicio de farmacia y en las unidades:","Se guardan bajo llave y su movimiento queda registrado",["Se guardan con el resto de la medicación","Los custodia el celador","Se almacenan en la nevera"],"El celador los traslada cerrados y los entrega en mano con firma de recepción.");
B(7,"T","Señale la INCORRECTA. Es función del celador en el servicio de farmacia:","Preparar las fórmulas magistrales",["Trasladar los pedidos de medicación a las unidades","Colaborar en la recepción y colocación de mercancías","Trasladar los carros de unidosis"],"La elaboración corresponde a farmacéuticos y técnicos de farmacia.");
B(7,"T","Cuando el celador traslada historias clínicas u otra documentación clínica:","No debe leerla ni mostrarla y debe entregarla en su destino sin demora",["Puede consultarla si tiene curiosidad","Puede dejársela a los familiares","Puede fotocopiarla para sí"],"Está sujeto al deber de confidencialidad.");
B(7,"T","El método de esterilización más utilizado en el hospital por su eficacia, rapidez y bajo coste es:","El vapor de agua a presión (autoclave)",["El óxido de etileno","El calor seco (Poupinel)","Las radiaciones gamma"],"Es un método físico por calor húmedo.");
B(7,"T","La estufa Poupinel esteriliza mediante:","Calor seco",["Calor húmedo","Gas plasma","Óxido de etileno"],"Su uso es hoy muy limitado.");
B(7,"T","El óxido de etileno es un método de esterilización:","Químico, a baja temperatura, que exige aireación posterior del material",["Físico por calor húmedo","Físico por radiaciones","Químico sin toxicidad alguna"],"Es tóxico e inflamable; se usa para material termosensible.");
B(7,"T","El test de Bowie-Dick se utiliza para:","Comprobar la extracción del aire y la penetración del vapor en autoclaves de prevacío",["Medir la toxicidad del óxido de etileno","Comprobar la temperatura de las neveras","Validar el lavado de manos"],"Se realiza diariamente con el autoclave vacío.");
B(7,"T","Los controles de esterilización que utilizan esporas bacterianas se denominan:","Controles biológicos",["Controles físicos","Controles químicos","Controles administrativos"],"Son los únicos que confirman la destrucción de microorganismos.");
B(7,"T","Señale el orden correcto de las zonas de una central de esterilización según el recorrido del material:","Sucia, limpia y estéril",["Estéril, limpia y sucia","Limpia, sucia y estéril","Sucia, estéril y limpia"],"El circuito es unidireccional para evitar cruces.");
B(7,"T","Antes de esterilizar el material es imprescindible:","Limpiarlo y secarlo",["Dejarlo sucio para no dañarlo","Mojarlo abundantemente","Engrasarlo"],"La suciedad impide el contacto del agente esterilizante.");
B(7,"T","Es función del celador en la central de esterilización:","Trasladar el material sucio a la central y el estéril a las unidades",["Decidir el método de esterilización","Interpretar los controles biológicos","Instrumentar"],"También puede colaborar en la carga y descarga de los equipos.");
B(7,"T","En el aseo del paciente encamado se sigue como norma general el orden:","De arriba abajo y de lo más limpio a lo más sucio",["De abajo arriba","De lo más sucio a lo más limpio","Indiferente"],"Se empieza por la cara y se termina por la región genital y anal.");
B(7,"T","En el aseo del paciente encamado, los ojos se limpian:","Del ángulo interno al externo, con una gasa distinta para cada ojo",["Del ángulo externo al interno","Con la misma esponja que el resto del cuerpo","Con jabón abundante"],"Se evita arrastrar secreciones hacia el conducto lagrimal.");
B(7,"T","La higiene de los genitales femeninos se realiza:","De delante hacia atrás",["De atrás hacia delante","En círculos","Es indiferente"],"Evita arrastrar gérmenes de la zona anal hacia la uretra y la vagina.");
B(7,"T","El aseo del paciente encamado es una función propia de:","El personal técnico en cuidados auxiliares de enfermería, con ayuda del celador para movilizar",["El celador en exclusiva","El médico","El personal de limpieza"],"El celador ayuda en los cambios de posición durante el aseo.");
B(7,"T","Las dimensiones de una hoja de formato DIN A4 son:","210 x 297 mm",["148 x 210 mm","297 x 420 mm","216 x 279 mm"],"148 x 210 es A5 y 297 x 420 es A3.");
B(7,"T","El formato DIN A3 equivale a:","Dos hojas DIN A4",["La mitad de un DIN A4","Cuatro hojas DIN A4","Un DIN A5"],"Cada formato de la serie A tiene el doble de superficie que el siguiente.");
B(7,"T","Señale la INCORRECTA. En el servicio de reprografía, el celador:","Repara las averías internas de las máquinas",["Realiza fotocopias y encuadernaciones","Repone papel y consumibles","Avisa de las averías que detecta"],"Las reparaciones corresponden al servicio técnico.");
B(7,"P","Traslada desde farmacia a planta un pedido que incluye estupefacientes. Al llegar debe:","Entregarlo en mano a la supervisora o enfermera responsable, que firmará la recepción",["Dejarlo en el control si no hay nadie","Entregarlo a un familiar","Guardarlo en su taquilla hasta el final del turno"],"Los estupefacientes requieren entrega personal y registro.");
B(7,"P","Le entregan en farmacia medicación termolábil para una unidad. Usted:","La traslada de inmediato, en su contenedor, sin romper la cadena de frío",["La reparte al final de su ruta","La lleva en el bolsillo","La deja en el control hasta que la pidan"],"Debe llegar a la nevera de destino lo antes posible.");
B(7,"P","Durante el traslado de varias historias clínicas, un conocido le pide ver la de su vecino. Usted:","Se niega; la documentación clínica es confidencial",["Se la deja un momento","Le dice el diagnóstico de palabra","Le hace una fotocopia"],"Acceder o facilitar el acceso sin autorización vulnera la confidencialidad.");
B(7,"P","Al recoger un paquete de material estéril para una planta, observa que el envoltorio está roto. Debe:","No distribuirlo y comunicarlo al personal de la central",["Entregarlo igualmente","Repararlo con cinta adhesiva","Usarlo solo si es urgente"],"Un envase roto o húmedo implica pérdida de la esterilidad.");
B(7,"P","Lleva en el mismo carro material sucio para esterilización y material estéril para repartir. Esto es:","Incorrecto; deben transportarse por separado",["Correcto si van en baldas distintas","Correcto si el trayecto es corto","Correcto si se cubren con una sábana"],"Los circuitos de sucio y limpio no deben cruzarse.");
B(7,"P","Ayuda a la TCAE en el aseo de un paciente encamado. Para lavar la espalda, usted:","Ayuda a colocar y sostener al paciente en decúbito lateral",["Lo incorpora tirando de los brazos","Lo deja en decúbito supino","Lo pone de pie junto a la cama"],"El celador colabora en la movilización durante el aseo.");
B(7,"P","En reprografía le encargan fotocopiar un informe clínico. Al terminar debe:","Retirar el original y todas las copias, sin dejar nada en la máquina",["Dejar una copia de reserva en la bandeja","Tirar las copias defectuosas a la papelera común","Guardar una copia por si se pierde"],"Las copias defectuosas con datos personales deben destruirse de forma segura.");
B(7,"P","Tiene que trasladar una muestra de sangre al laboratorio. Lo correcto es:","Llevarla en el contenedor adecuado, en posición vertical, con su petición y sin demora",["Llevarla en el bolsillo","Agitarla durante el trayecto","Dejarla en el mostrador de información"],"Deben evitarse derrames, roturas y retrasos.");

/* ================= TEMA 8: Urgencias, entrada de urgencias, transporte en ambulancia ================= */
B(8,"T","La situación en la que existe un riesgo inmediato para la vida del paciente o para la función de un órgano se denomina:","Emergencia",["Urgencia demorable","Consulta programada","Urgencia subjetiva"],"En la urgencia la atención no debe demorarse, pero no hay riesgo vital inmediato.");
B(8,"T","El proceso de clasificación de los pacientes según su gravedad a su llegada a urgencias se denomina:","Triaje",["Admisión","Filiación","Anamnesis"],"Determina la prioridad de la atención, no el diagnóstico.");
B(8,"T","El triaje en los servicios de urgencias hospitalarios lo realiza habitualmente:","El personal de enfermería",["El celador","El personal de admisión","El vigilante de seguridad"],"El celador conduce al paciente a la zona de triaje.");
B(8,"T","En el Sistema de Triaje Manchester, el color rojo significa:","Atención inmediata",["Muy urgente","Urgente","No urgente"],"Hay cinco niveles: rojo, naranja, amarillo, verde y azul.");
B(8,"T","En el Sistema de Triaje Manchester, el color azul corresponde a un paciente:","No urgente",["Muy urgente","Urgente","De atención inmediata"],"Es el nivel de menor prioridad.");
B(8,"T","En el Sistema de Triaje Manchester, el nivel 'muy urgente' se identifica con el color:","Naranja",["Amarillo","Verde","Rojo"],"El amarillo corresponde a 'urgente' y el verde a 'normal o menos urgente'.");
B(8,"T","¿Cuántos niveles de prioridad establece el Sistema de Triaje Manchester?","Cinco",["Tres","Cuatro","Seis"],"Cada nivel tiene asignado un color y un tiempo máximo de espera.");
B(8,"T","Señale la INCORRECTA. Es función del celador en la puerta de urgencias:","Decidir la prioridad de atención de los pacientes",["Recibir a los pacientes y ayudarles a salir del vehículo","Proporcionar silla de ruedas o camilla","Trasladar a los pacientes a la zona indicada"],"La prioridad la establece el triaje.");
B(8,"T","El teléfono único europeo de emergencias es el:","112",["061","091","016"],"El 061 es el de Urxencias Sanitarias de Galicia.");
B(8,"T","En Galicia, el teléfono de urgencias sanitarias es el:","061",["062","092","080"],"Gestionado por la Fundación Pública Urxencias Sanitarias de Galicia-061.");
B(8,"T","La norma que establece las características técnicas, el equipamiento y la dotación de personal de los vehículos de transporte sanitario por carretera es:","El Real Decreto 836/2012, de 25 de mayo",["La Ley 14/1986, de 25 de abril","El Real Decreto 521/1987","La Ley 55/2003"],"Clasifica las ambulancias en clases A, B y C.");
B(8,"T","Según el Real Decreto 836/2012, las ambulancias de clase B son:","Asistenciales de soporte vital básico",["No asistenciales convencionales","De transporte colectivo","Asistenciales de soporte vital avanzado"],"Clase A: no asistenciales; clase C: soporte vital avanzado.");
B(8,"T","Según el Real Decreto 836/2012, las ambulancias de clase A2 son:","De transporte colectivo",["Convencionales de traslado individual en camilla","De soporte vital básico","De soporte vital avanzado"],"Las A1 son las convencionales.");
B(8,"T","Las ambulancias de soporte vital avanzado pertenecen a la clase:","C",["A1","A2","B"],"Su dotación incluye personal de enfermería y, cuando la asistencia lo requiera, médico.");
B(8,"T","En la reanimación cardiopulmonar básica del adulto, la relación entre compresiones y ventilaciones es:","30 compresiones y 2 ventilaciones",["15 compresiones y 2 ventilaciones","5 compresiones y 1 ventilación","30 compresiones y 5 ventilaciones"],"Con uno o dos reanimadores.");
B(8,"T","La frecuencia recomendada de las compresiones torácicas en la RCP del adulto es de:","100 a 120 por minuto",["60 a 80 por minuto","80 a 90 por minuto","140 a 160 por minuto"],"Con una profundidad de 5 a 6 cm.");
B(8,"T","Las siglas DESA corresponden a:","Desfibrilador externo semiautomático",["Dispositivo de emergencia sanitaria avanzada","Desfibrilador estándar de sala","Dispositivo externo de soporte aéreo"],"Analiza el ritmo e indica si procede la descarga.");
B(8,"T","La movilización de un paciente politraumatizado debe hacerse:","En bloque, manteniendo alineado el eje cabeza-cuello-tronco",["Sentándolo primero","Tirando de las extremidades","Girando solo la cabeza"],"Se evita agravar posibles lesiones medulares.");
B(8,"T","En el traslado en ambulancia, el paciente consciente sin otras indicaciones se coloca generalmente:","En decúbito supino con la cabecera algo elevada (semi-Fowler)",["En decúbito prono","En Trendelenburg","De pie sujeto a las barras"],"La posición se adapta a la patología por indicación sanitaria.");
B(8,"T","El control del acceso de acompañantes a la zona asistencial de urgencias corresponde a:","El celador, según las normas del centro",["El paciente","Los propios acompañantes","El conductor de la ambulancia"],"Como norma general se limita el número de acompañantes por paciente.");
B(8,"P","Llega a la puerta de urgencias un coche particular con una persona que no puede caminar. Usted:","Acude con una silla de ruedas o camilla, le ayuda a salir y lo traslada a la zona de triaje",["Le indica que espere a que llegue una ambulancia","Le pide que entre andando","Va primero a admisión a dar sus datos"],"La recepción y ayuda al paciente es función del celador de puerta.");
B(8,"P","Llega una ambulancia con un paciente inconsciente. Su actuación será:","Ayudar a pasarlo a la camilla y trasladarlo de inmediato a la zona indicada, avisando al personal sanitario",["Pedir primero la tarjeta sanitaria","Dejarlo en la sala de espera","Esperar a que se filie en admisión"],"En la emergencia la asistencia es prioritaria sobre los trámites.");
B(8,"P","En la sala de espera de urgencias una persona se desploma y no responde. Lo primero que debe hacer es:","Pedir ayuda al personal sanitario y comprobar si respira",["Darle agua","Sentarla en una silla","Ir a buscar a su familia"],"Si no respira con normalidad se inicia la RCP.");
B(8,"P","Un acompañante, alterado por la espera, comienza a gritar y a amenazar al personal. Usted:","Mantiene la calma, intenta tranquilizarle sin enfrentarse y avisa a seguridad si persiste",["Le grita más fuerte","Le empuja fuera del servicio","Le adelanta en la lista de espera"],"No se debe responder con agresividad ni alterar el orden de atención.");
B(8,"P","Llega un paciente accidentado de tráfico al que los técnicos traen con collarín y tablero espinal. Para pasarlo a la camilla del hospital:","Se moviliza en bloque, coordinados y siguiendo las indicaciones del personal sanitario",["Se le pide que se incorpore","Se retira el collarín para que esté cómodo","Lo pasa usted solo tirando de la sábana"],"No debe retirarse la inmovilización sin indicación.");
B(8,"P","Un paciente clasificado como verde en el triaje le exige pasar antes que otro que acaba de llegar y entra directamente. Usted:","Le explica que el orden de atención depende de la gravedad y no de la hora de llegada",["Le cuela para evitar problemas","Le dice que el otro paciente tiene enchufe","Le indica que reclame al médico en el box"],"El triaje prioriza por gravedad.");
B(8,"P","Le indican que acompañe en ambulancia el traslado de un paciente a otro centro. Durante el trayecto, usted:","Ayuda en la movilización y sigue las instrucciones del personal sanitario",["Decide la velocidad de la ambulancia","Administra la medicación pautada","Informa a la familia del diagnóstico"],"El traslado de enfermos en el servicio de ambulancias es función del celador (función 12ª).");
B(8,"P","En urgencias le entregan unas muestras y una petición de transfusión para llevar con urgencia. Lo correcto es:","Llevarlas de inmediato a su destino y entregarlas en mano",["Esperar a reunir más encargos","Dejarlas en el tubo de admisión","Pedir a un familiar que las lleve"],"Los encargos urgentes se tramitan sin demora.");

/* ================= TEMA 9: Informática, ofimática, internet, correo electrónico ================= */
B(9,"T","El conjunto de componentes físicos de un ordenador se denomina:","Hardware",["Software","Firmware","Malware"],"El software es el conjunto de programas.");
B(9,"T","La memoria RAM se caracteriza por ser:","Volátil: pierde su contenido al apagar el equipo",["De solo lectura","Permanente","Un periférico de salida"],"La ROM es de solo lectura y no volátil.");
B(9,"T","Un byte equivale a:","8 bits",["4 bits","10 bits","1024 bits"],"El bit es la unidad mínima de información.");
B(9,"T","Señale cuál de los siguientes es un periférico de entrada:","Escáner",["Impresora","Monitor","Altavoces"],"Teclado, ratón, escáner y micrófono son periféricos de entrada.");
B(9,"T","Señale cuál de los siguientes NO es un sistema operativo:","Excel",["Windows","Linux","macOS"],"Excel es una hoja de cálculo.");
B(9,"T","¿Cuál de los siguientes programas es un procesador de textos?","Writer",["Calc","Excel","Outlook"],"Writer (LibreOffice) y Word (Microsoft) son procesadores de texto.");
B(9,"T","En una hoja de cálculo, la intersección de una fila y una columna se denomina:","Celda",["Rango","Libro","Registro"],"Se identifica por la letra de la columna y el número de la fila.");
B(9,"T","En una hoja de cálculo, las fórmulas comienzan con el signo:","=",["#","&","%"],"Por ejemplo, =SUMA(A1:A5).");
B(9,"T","La combinación de teclas para copiar el elemento seleccionado es:","Ctrl + C",["Ctrl + V","Ctrl + X","Ctrl + Z"],"Ctrl+V pega, Ctrl+X corta y Ctrl+Z deshace.");
B(9,"T","La combinación de teclas Ctrl + Z sirve para:","Deshacer la última acción",["Guardar","Imprimir","Seleccionar todo"],"Ctrl+P abre el cuadro de impresión.");
B(9,"T","La extensión habitual de un documento de Microsoft Word es:",".docx",[".xlsx",".pptx",".jpg"],".xlsx corresponde a Excel y .pptx a PowerPoint.");
B(9,"T","El programa que permite visualizar páginas web se denomina:","Navegador",["Buscador","Servidor","Cortafuegos"],"Ejemplos: Chrome, Firefox, Edge. Google es un buscador.");
B(9,"T","El protocolo que indica que la conexión con una página web está cifrada es:","HTTPS",["HTTP","FTP","SMTP"],"La S indica 'seguro'.");
B(9,"T","En un correo electrónico, el campo CCO sirve para:","Enviar copia a destinatarios sin que el resto vea sus direcciones",["Enviar una copia visible para todos","Adjuntar archivos","Indicar el asunto"],"CCO: con copia oculta.");
B(9,"T","La técnica de engaño que busca obtener contraseñas o datos personales suplantando a una entidad de confianza se denomina:","Phishing",["Spam","Cookie","Backup"],"El spam es correo no deseado, generalmente publicitario.");
B(9,"T","La red privada de una organización, accesible solo a su personal, se denomina:","Intranet",["Internet","Extranet pública","Wifi abierta"],"Utiliza la misma tecnología que internet pero con acceso restringido.");
B(9,"P","Recibe en su correo corporativo un mensaje que le pide con urgencia su usuario y contraseña a través de un enlace. Debe:","No facilitar los datos ni pulsar el enlace y comunicarlo según el procedimiento del centro",["Responder con sus claves","Reenviarlo a todos sus compañeros","Pulsar el enlace para comprobar si es real"],"Es un intento típico de phishing.");
B(9,"P","Debe ausentarse unos minutos del puesto de información con el ordenador encendido. Lo correcto es:","Bloquear la sesión",["Dejar la pantalla abierta","Apuntar su contraseña en un papel junto al teclado","Pedir a un visitante que vigile"],"Evita accesos no autorizados a datos personales.");
B(9,"P","Un compañero le pide su usuario y contraseña porque ha olvidado los suyos. Usted:","No se los facilita; las credenciales son personales e intransferibles",["Se los deja por esta vez","Se los apunta en un papel","Se los envía por correo"],"Cada acceso queda registrado a nombre del titular.");
B(9,"P","Tiene que enviar un mismo aviso por correo a muchos usuarios externos sin que vean las direcciones de los demás. Usará el campo:","CCO",["Para","CC","Asunto"],"Protege los datos personales de los destinatarios.");

/* ================= TEMA 10: Perspectiva de género, salud y género, violencia de género ================= */
B(10,"T","El conjunto de características biológicas que diferencian a mujeres y hombres se denomina:","Sexo",["Género","Rol","Estereotipo"],"El género es una construcción social y cultural.");
B(10,"T","El conjunto de roles, comportamientos y atributos que una sociedad considera apropiados para mujeres y hombres se denomina:","Género",["Sexo","Genotipo","Fenotipo"],"Varía según la cultura y la época.");
B(10,"T","La integración del principio de igualdad en todas las políticas y actuaciones se denomina:","Transversalidad de género o mainstreaming",["Discriminación positiva","Paridad","Coeducación"],"Supone tener en cuenta el impacto sobre mujeres y hombres en todas las decisiones.");
B(10,"T","La Ley Orgánica de Medidas de Protección Integral contra la Violencia de Género es la:","Ley Orgánica 1/2004, de 28 de diciembre",["Ley Orgánica 3/2007, de 22 de marzo","Ley 11/2007, de 27 de julio","Ley 55/2003, de 16 de diciembre"],"La LO 3/2007 es la de igualdad efectiva de mujeres y hombres.");
B(10,"T","La ley gallega para la prevención y el tratamiento integral de la violencia de género es la:","Ley 11/2007, de 27 de julio",["Ley 8/2008, de 10 de julio","Ley Orgánica 1/2004, de 28 de diciembre","Ley 3/2001, de 28 de mayo"],"La Ley 8/2008 es la de salud de Galicia.");
B(10,"T","La Ley Orgánica para la igualdad efectiva de mujeres y hombres es la:","Ley Orgánica 3/2007, de 22 de marzo",["Ley Orgánica 1/2004, de 28 de diciembre","Ley Orgánica 15/1999","Ley 14/1986"],"Establece, entre otras medidas, los planes de igualdad.");
B(10,"T","Según la Ley Orgánica 1/2004, la violencia de género es la que se ejerce sobre las mujeres por parte de:","Quienes sean o hayan sido sus cónyuges o estén o hayan estado ligados a ellas por relaciones similares de afectividad, aun sin convivencia",["Cualquier familiar que conviva con ellas","Únicamente su cónyuge actual","Cualquier persona en el ámbito laboral"],"Artículo 1 de la Ley Orgánica 1/2004.");
B(10,"T","El teléfono estatal de información y asesoramiento en materia de violencia de género es el:","016",["061","112","012"],"Es gratuito y no aparece en la factura, aunque debe borrarse del registro de llamadas del teléfono.");
B(10,"T","Según el modelo de Leonore Walker, las fases del ciclo de la violencia son:","Acumulación de tensión, explosión o agresión y luna de miel o arrepentimiento",["Negación, ira y aceptación","Agresión, denuncia y separación","Inicio, mantenimiento y abandono"],"El ciclo tiende a repetirse y a acortarse.");
B(10,"T","La violencia que se ejerce sobre los hijos e hijas con el fin de causar daño a la mujer se denomina:","Violencia vicaria",["Violencia económica","Violencia institucional","Violencia simbólica"],"Es una de las formas más extremas de violencia de género.");
B(10,"T","El Día Internacional de la Eliminación de la Violencia contra la Mujer se celebra el:","25 de noviembre",["8 de marzo","1 de mayo","10 de diciembre"],"El 8 de marzo es el Día Internacional de la Mujer.");
B(10,"T","La barrera invisible que dificulta el acceso de las mujeres a los puestos de mayor responsabilidad se conoce como:","Techo de cristal",["Suelo pegajoso","Brecha digital","Espejismo de la igualdad"],"El 'suelo pegajoso' alude a las dificultades para abandonar los puestos más bajos.");
B(10,"T","El documento médico-legal que se remite al juzgado cuando se atienden lesiones presuntamente causadas por una agresión es:","El parte de lesiones",["El informe de alta","El consentimiento informado","La hoja de interconsulta"],"Lo emite el personal facultativo.");
B(10,"T","Señale la INCORRECTA. Privar a la mujer de recursos económicos o impedirle el acceso a ellos es:","Una forma de violencia que no reconoce la normativa",["Violencia económica","Una forma de violencia de género","Una forma de control sobre la mujer"],"La Ley gallega 11/2007 recoge expresamente la violencia económica.");
B(10,"T","La diferente forma de enfermar de mujeres y hombres, por razones biológicas y sociales, se denomina:","Morbilidad diferencial",["Mortalidad infantil","Esperanza de vida","Prevalencia"],"Ignorarla produce sesgos de género en la atención sanitaria.");
B(10,"T","Considerar como norma lo observado en los hombres y aplicarlo sin más a las mujeres en la atención sanitaria constituye:","Un sesgo de género",["Una acción positiva","Una medida de conciliación","Un plan de igualdad"],"Puede provocar retrasos diagnósticos y tratamientos inadecuados.");
B(10,"P","Mientras traslada a una paciente, esta le cuenta que su pareja la agrede y le pide que no se lo diga a nadie. Usted:","La escucha sin juzgarla y lo pone en conocimiento del personal sanitario responsable",["Guarda el secreto y no hace nada","Le dice que debería haber denunciado antes","Se lo comenta a sus compañeros en el descanso"],"El personal sanitario activará el protocolo de actuación.");
B(10,"P","En urgencias, el acompañante de una paciente con lesiones no la deja sola en ningún momento y responde por ella. Usted sospecha de maltrato. Debe:","Comunicar su sospecha discretamente al personal sanitario",["Enfrentarse al acompañante","Preguntar a la paciente delante de él","No intervenir porque es un asunto privado"],"La entrevista a solas la gestionará el personal sanitario.");
B(10,"P","El personal sanitario le indica que una paciente víctima de violencia de género no debe recibir visitas de su pareja. Si este se presenta en el control de accesos, usted:","No le facilita ningún dato ni el acceso y avisa según el protocolo del centro",["Le indica la habitación","Le dice que vuelva más tarde","Le confirma que está ingresada pero no puede pasar"],"No debe confirmarse ni siquiera el ingreso.");
B(10,"P","Una compañera le comenta que un superior le hace insinuaciones sexuales no deseadas de forma reiterada. Lo adecuado es:","Informarle de que existe un protocolo frente al acoso sexual y animarla a utilizarlo",["Decirle que no le dé importancia","Aconsejarle que cambie de turno y lo olvide","Difundirlo entre el resto del personal"],"El acoso sexual en el trabajo es una forma de violencia contra las mujeres.");
